<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>WastedToken Mint | Proof-Grade Challenge Coins</title>
  <style>
    :root {
      --bg: #090a0f;
      --bg-surface: #11141e;
      --bg-card: #141824;
      --border: rgba(255, 255, 255, 0.08);
      --border-bright: rgba(212, 175, 55, 0.35);
      --gold: #d4af37;
      --gold-bright: #ffd700;
      --gold-dark: #8c6d1f;
      --silver: #c8d1dc;
      --bronze: #cd7f32;
      --obsidian: #3a3f4d;
      --text: #e2e8f0;
      --text-muted: #8e9bb0;
      --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
      --font-display: "Cinzel", "Trajan Pro", "Georgia", serif;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      background-color: var(--bg);
      color: var(--text);
      font-family: var(--font);
      line-height: 1.6;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
      background-image: 
        radial-gradient(circle at 50% 15%, rgba(212, 175, 55, 0.07) 0%, transparent 60%),
        radial-gradient(circle at 85% 60%, rgba(56, 80, 140, 0.05) 0%, transparent 50%);
    }

    /* Header & Navigation */
    header {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      z-index: 100;
      padding: 1.25rem 2.5rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
      backdrop-filter: blur(16px);
      background: rgba(9, 10, 15, 0.8);
      border-bottom: 1px solid var(--border);
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      text-decoration: none;
      color: #fff;
    }

    .brand-mark {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: radial-gradient(circle at 35% 35%, var(--gold-bright), var(--gold-dark));
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 900;
      font-size: 16px;
      color: #090a0f;
      box-shadow: 0 0 15px rgba(212, 175, 55, 0.4);
    }

    .brand-name {
      font-family: var(--font-display);
      font-weight: 700;
      letter-spacing: 0.15em;
      font-size: 1.15rem;
      text-transform: uppercase;
      background: linear-gradient(135deg, #ffffff 40%, var(--gold) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
    }

    nav {
      display: flex;
      gap: 2rem;
    }

    nav a {
      color: var(--text-muted);
      text-decoration: none;
      font-size: 0.9rem;
      font-weight: 500;
      letter-spacing: 0.05em;
      text-transform: uppercase;
      transition: color 0.2s ease;
    }

    nav a:hover {
      color: var(--gold);
    }

    /* Hero Section */
    .hero {
      position: relative;
      min-height: 94vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 6rem 1.5rem 3rem;
      text-align: center;
    }

    .hero-eyebrow {
      font-size: 0.8rem;
      text-transform: uppercase;
      letter-spacing: 0.3em;
      color: var(--gold);
      margin-bottom: 0.75rem;
      font-weight: 600;
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
    }
    .hero-eyebrow::before, .hero-eyebrow::after {
      content: "";
      width: 24px;
      height: 1px;
      background: var(--gold-dark);
    }

    .hero-title {
      font-family: var(--font-display);
      font-size: clamp(2.2rem, 5.5vw, 4.2rem);
      line-height: 1.1;
      font-weight: 800;
      letter-spacing: 0.02em;
      margin-bottom: 1rem;
      max-width: 900px;
      background: linear-gradient(180deg, #ffffff 30%, #a4b3ca 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      text-shadow: 0 10px 30px rgba(0,0,0,0.5);
    }

    .hero-desc {
      color: var(--text-muted);
      font-size: clamp(1rem, 1.8vw, 1.2rem);
      max-width: 620px;
      margin-bottom: 1.5rem;
      font-weight: 300;
    }

    /* Coin Stage */
    .coin-stage {
      position: relative;
      width: 100%;
      max-width: 540px;
      aspect-ratio: 1 / 1;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0.5rem auto 1.5rem;
    }

    .stage-glow {
      position: absolute;
      width: 75%;
      height: 75%;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(212, 175, 55, 0.18) 0%, rgba(212, 175, 55, 0.03) 50%, transparent 70%);
      filter: blur(25px);
      pointer-events: none;
      z-index: 1;
    }

    .stage-pedestal {
      position: absolute;
      bottom: 6%;
      width: 60%;
      height: 24px;
      background: radial-gradient(ellipse at center, rgba(0,0,0,0.85) 0%, rgba(0,0,0,0) 70%);
      filter: blur(8px);
      z-index: 1;
    }

    #coin-hero {
      position: relative;
      width: 100%;
      height: 100%;
      z-index: 2;
      display: block;
    }

    .coin-stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1.5rem;
      max-width: 650px;
      width: 100%;
      margin-top: 1rem;
      padding: 1.25rem;
      border: 1px solid var(--border);
      border-radius: 12px;
      background: rgba(17, 20, 30, 0.6);
      backdrop-filter: blur(10px);
    }

    .stat-item {
      display: flex;
      flex-direction: column;
      align-items: center;
    }

    .stat-val {
      font-size: 1.25rem;
      font-weight: 700;
      color: #fff;
      font-family: var(--font-display);
    }

    .stat-label {
      font-size: 0.72rem;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--text-muted);
      margin-top: 0.2rem;
    }

    /* Sections Shared */
    section {
      padding: 6rem 1.5rem;
      max-width: 1280px;
      margin: 0 auto;
    }

    .section-header {
      text-align: center;
      margin-bottom: 4rem;
    }

    .section-tag {
      font-size: 0.8rem;
      text-transform: uppercase;
      letter-spacing: 0.25em;
      color: var(--gold);
      font-weight: 600;
      display: block;
      margin-bottom: 0.5rem;
    }

    .section-title {
      font-family: var(--font-display);
      font-size: clamp(2rem, 3.5vw, 2.8rem);
      font-weight: 700;
      color: #fff;
      letter-spacing: 0.02em;
    }

    .section-subtitle {
      color: var(--text-muted);
      max-width: 600px;
      margin: 0.75rem auto 0;
      font-size: 1.05rem;
    }

    /* About Section */
    .about-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 3.5rem;
      align-items: center;
      margin-bottom: 4rem;
    }

    @media (max-width: 860px) {
      .about-grid {
        grid-template-columns: 1fr;
        gap: 2rem;
      }
    }

    .about-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: 16px;
      padding: 2.75rem;
      position: relative;
      overflow: hidden;
    }

    .about-card::before {
      content: "";
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 3px;
      background: linear-gradient(90deg, var(--gold-dark), var(--gold-bright), transparent);
    }

    .about-card h3 {
      font-family: var(--font-display);
      font-size: 1.75rem;
      margin-bottom: 1rem;
      color: #fff;
    }

    .about-card p {
      color: var(--text-muted);
      margin-bottom: 1.25rem;
      font-size: 1rem;
    }

    .spec-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 0.85rem;
      margin-top: 1.5rem;
      padding-top: 1.5rem;
      border-top: 1px solid var(--border);
    }

    .spec-list li {
      display: flex;
      justify-content: space-between;
      font-size: 0.9rem;
    }

    .spec-list span:first-child {
      color: var(--text-muted);
    }

    .spec-list span:last-child {
      color: #fff;
      font-weight: 600;
    }

    .about-pillars {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1.5rem;
    }

    @media (max-width: 520px) {
      .about-pillars {
        grid-template-columns: 1fr;
      }
    }

    .pillar-box {
      background: var(--bg-surface);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 1.5rem;
      transition: border-color 0.3s ease, transform 0.3s ease;
    }

    .pillar-box:hover {
      border-color: var(--border-bright);
      transform: translateY(-3px);
    }

    .pillar-icon {
      font-size: 1.5rem;
      margin-bottom: 0.75rem;
      display: inline-block;
      color: var(--gold);
    }

    .pillar-title {
      font-family: var(--font-display);
      font-size: 1.1rem;
      color: #fff;
      margin-bottom: 0.4rem;
    }

    .pillar-desc {
      font-size: 0.85rem;
      color: var(--text-muted);
      line-height: 1.5;
    }

    /* Editions Collection Grid */
    .editions-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1.75rem;
    }

    @media (max-width: 1080px) {
      .editions-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (max-width: 580px) {
      .editions-grid {
        grid-template-columns: 1fr;
      }
    }

    .edition {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: 16px;
      padding: 1.75rem 1.5rem;
      display: flex;
      flex-direction: column;
      align-items: center;
      text-align: center;
      position: relative;
      transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
    }

    .edition:hover {
      transform: translateY(-6px);
      box-shadow: 0 16px 36px rgba(0, 0, 0, 0.45);
      border-color: rgba(255, 255, 255, 0.2);
    }

    .edition[data-state="sold-out"] {
      opacity: 0.78;
      border-style: dashed;
    }

    .edition[data-state="coming-soon"] {
      background: linear-gradient(180deg, #12141f 0%, #0d0e15 100%);
      border-color: rgba(90, 105, 130, 0.3);
    }

    .edition-badge {
      position: absolute;
      top: 14px;
      right: 14px;
      font-size: 0.65rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      padding: 0.25rem 0.6rem;
      border-radius: 50px;
    }

    .edition[data-state="available"] .edition-badge {
      background: rgba(34, 197, 94, 0.15);
      color: #4ade80;
      border: 1px solid rgba(74, 222, 128, 0.3);
    }

    .edition[data-state="sold-out"] .edition-badge {
      background: rgba(239, 68, 68, 0.15);
      color: #f87171;
      border: 1px solid rgba(248, 113, 113, 0.3);
    }

    .edition[data-state="coming-soon"] .edition-badge {
      background: rgba(148, 163, 184, 0.15);
      color: #94a3b8;
      border: 1px solid rgba(148, 163, 184, 0.3);
    }

    .edition-canvas-wrapper {
      width: 100%;
      aspect-ratio: 1 / 1;
      max-width: 210px;
      margin: 1rem 0 1.25rem;
      position: relative;
    }

    .edition-canvas {
      width: 100%;
      height: 100%;
      display: block;
      border-radius: 50%;
    }

    .edition-name {
      font-family: var(--font-display);
      font-size: 1.3rem;
      color: #fff;
      font-weight: 700;
      margin-bottom: 0.35rem;
    }

    .edition-sub {
      font-size: 0.8rem;
      color: var(--text-muted);
      margin-bottom: 0.75rem;
      text-transform: uppercase;
      letter-spacing: 0.08em;
    }

    .edition-desc {
      font-size: 0.85rem;
      color: #9aa4b5;
      margin-bottom: 1.25rem;
      flex-grow: 1;
      line-height: 1.5;
    }

    .edition-meta {
      display: flex;
      justify-content: space-between;
      width: 100%;
      font-size: 0.8rem;
      color: var(--text-muted);
      padding: 0.75rem 0;
      border-top: 1px solid var(--border);
      margin-bottom: 1.25rem;
    }

    .edition-price {
      font-family: var(--font-display);
      font-size: 1.15rem;
      color: #fff;
      font-weight: 700;
    }

    /* Buttons */
    .buy {
      width: 100%;
      padding: 0.85rem 1.25rem;
      border-radius: 8px;
      font-family: var(--font);
      font-size: 0.88rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      cursor: pointer;
      transition: all 0.25s ease;
      background: linear-gradient(135deg, var(--gold) 0%, var(--gold-dark) 100%);
      color: #0b0d13;
      border: 1px solid var(--gold-bright);
      box-shadow: 0 4px 14px rgba(212, 175, 55, 0.25);
    }

    .buy:hover:not(:disabled) {
      filter: brightness(1.15);
      box-shadow: 0 6px 20px rgba(212, 175, 55, 0.4);
      transform: translateY(-2px);
    }

    .buy:active:not(:disabled) {
      transform: translateY(0);
    }

    .buy:disabled {
      background: #1d212d;
      color: #555e70;
      border: 1px solid rgba(255, 255, 255, 0.05);
      cursor: not-allowed;
      box-shadow: none;
      transform: none;
    }

    /* Footer */
    footer {
      border-top: 1px solid var(--border);
      background: #06070a;
      padding: 4rem 1.5rem 3rem;
      margin-top: 4rem;
      color: var(--text-muted);
      font-size: 0.88rem;
    }

    .footer-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 1.5rem;
    }

    .footer-copy {
      color: #616e84;
      font-size: 0.82rem;
    }

    /* Interactive cart notification toast */
    .toast {
      position: fixed;
      bottom: 2rem;
      right: 2rem;
      background: #111522;
      border: 1px solid var(--gold);
      color: #fff;
      padding: 1rem 1.5rem;
      border-radius: 8px;
      box-shadow: 0 10px 30px rgba(0,0,0,0.7);
      transform: translateY(120px);
      opacity: 0;
      transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
      z-index: 1000;
      display: flex;
      align-items: center;
      gap: 0.75rem;
    }

    .toast.show {
      transform: translateY(0);
      opacity: 1;
    }
  </style>
</head>
<body>

  <!-- Navigation -->
  <header>
    <a href="#" class="brand">
      <div class="brand-mark">W</div>
      <span class="brand-name">WastedToken Mint</span>
    </a>
    <nav>
      <a href="#hero">The Coin</a>
      <a href="#about">Craft</a>
      <a href="#collection">Editions</a>
    </nav>
  </header>

  <!-- Hero Section -->
  <section class="hero" id="hero">
    <span class="hero-eyebrow">Proof-Grade Numismatics</span>
    <h1 class="hero-title">Tangible Worth in an Ephemeral World</h1>
    <p class="hero-desc">
      Ultra-high relief challenge coins struck from solid metallurgical alloys.
      Precision-reeded, individually numbered, and minted for those who held the line.
    </p>

    <!-- Coin Hero Container -->
    <div class="coin-stage">
      <div class="stage-glow"></div>
      <canvas id="coin-hero" width="600" height="600"></canvas>
      <div class="stage-pedestal"></div>
    </div>

    <div class="coin-stats">
      <div class="stat-item">
        <span class="stat-val">44.5 mm</span>
        <span class="stat-label">Diameter</span>
      </div>
      <div class="stat-item">
        <span class="stat-val">3.5 mm</span>
        <span class="stat-label">Proof Thickness</span>
      </div>
      <div class="stat-item">
        <span class="stat-val">120 Reeds</span>
        <span class="stat-label">Precision Edge</span>
      </div>
    </div>
  </section>

  <!-- About Section -->
  <section id="about">
    <div class="section-header">
      <span class="section-tag">Forged In Integrity</span>
      <h2 class="section-title">The Art of Challenge Coinage</h2>
      <p class="section-subtitle">
        We bridge the digital void with unyielding mass, industrial precision, and timeless metallurgical heritage.
      </p>
    </div>

    <div class="about-grid">
      <div class="about-card">
        <h3>Struck Under 200 Metric Tons</h3>
        <p>
          Challenge coins originated as clandestine identifiers of unit brotherhood. At WastedToken Mint,
          we restore that sacred ritual. Every specimen undergoes multi-strike hydraulic die stamping,
          inducing deep 3D sculptural topography before undergoing hand-lapped mirror proofing.
        </p>
        <p>
          Whether carried as a pocket talisman, slammed on the bar in camaraderie, or encased in vault archives,
          your coin possesses true heft and undeniable physical presence.
        </p>
        <ul class="spec-list">
          <li><span>Relief Profile</span> <span>Multi-Level 3D Sculpted</span></li>
          <li><span>Edge Treatment</span> <span>Standard Reeded Coin Edge (120 Grooves)</span></li>
          <li><span>Surface Finish</span> <span>Antiqued &amp; High-Polish Dual Luster</span></li>
          <li><span>Origin</span> <span>Solid Billet Stock • Precision Lathe Finished</span></li>
        </ul>
      </div>

      <div class="about-pillars">
        <div class="pillar-box">
          <div class="pillar-icon">&#9879;</div>
          <h4 class="pillar-title">Solid Alloy Billets</h4>
          <p class="pillar-desc">No zinc fillers or cheap die-cast slop. Only heavyweight copper, solid brass, 999 fine silver cladding, and carbonized alloys.</p>
        </div>
        <div class="pillar-box">
          <div class="pillar-icon">&#9670;</div>
          <h4 class="pillar-title">Flawless Reeding</h4>
          <p class="pillar-desc">Reeded outer circumference machined to exact anti-counterfeiting specs, creating distinct tactile feedback when rolled across knuckles.</p>
        </div>
        <div class="pillar-box">
          <div class="pillar-icon">&#9733;</div>
          <h4 class="pillar-title">Cryptographic Serial</h4>
          <p class="pillar-desc">Each coin features a laser-etched serial key along the inner ring, permanently pairing the physical relic to the mint registry.</p>
        </div>
        <div class="pillar-box">
          <div class="pillar-icon">&#9830;</div>
          <h4 class="pillar-title">Dual-Sided Contrast</h4>
          <p class="pillar-desc">Deep bas-relief obverse emblem meets high-clarity reverse denomination, framed by micro-inscribed concentric borders.</p>
        </div>
      </div>
    </div>
  </section>

  <!-- Editions Collection Grid -->
  <section id="collection">
    <div class="section-header">
      <span class="section-tag">Archive Editions</span>
      <h2 class="section-title">Genesis Series Minting</h2>
      <p class="section-subtitle">
        Four metallurgical tiers commemorating the digital reckoning. Choose your weight.
      </p>
    </div>

    <div class="editions-grid">
      <!-- 1. Bronze (available) -->
      <div class="edition" data-edition="bronze" data-state="available">
        <span class="edition-badge">Available</span>
        <div class="edition-canvas-wrapper">
          <canvas class="edition-canvas" width="280" height="280"></canvas>
        </div>
        <h3 class="edition-name">Cuprum Bronze</h3>
        <span class="edition-sub">Edition I &bull; 1,000 Mintage</span>
        <p class="edition-desc">
          Warm antiqued naval bronze with fire-oxidized lowlands and polished highlights. Heavyweight hand-feel.
        </p>
        <div class="edition-meta">
          <span>Denomination</span>
          <span class="edition-price">1,000 TOKENS</span>
        </div>
        <button class="buy" onclick="handleAddToCart('Cuprum Bronze')">Add to cart</button>
      </div>

      <!-- 2. Silver (available) -->
      <div class="edition" data-edition="silver" data-state="available">
        <span class="edition-badge">Available</span>
        <div class="edition-canvas-wrapper">
          <canvas class="edition-canvas" width="280" height="280"></canvas>
        </div>
        <h3 class="edition-name">Sterling Silver</h3>
        <span class="edition-sub">Edition II &bull; 500 Mintage</span>
        <p class="edition-desc">
          Brilliant rhodium-plated sterling alloy with frosted cameo relief and pristine mirror proof fields.
        </p>
        <div class="edition-meta">
          <span>Denomination</span>
          <span class="edition-price">5,000 TOKENS</span>
        </div>
        <button class="buy" onclick="handleAddToCart('Sterling Silver')">Add to cart</button>
      </div>

      <!-- 3. Gold (sold out) -->
      <div class="edition" data-edition="gold" data-state="sold-out">
        <span class="edition-badge">SOLD OUT</span>
        <div class="edition-canvas-wrapper">
          <canvas class="edition-canvas" width="280" height="280"></canvas>
        </div>
        <h3 class="edition-name">Imperial Aurum</h3>
        <span class="edition-sub">Edition III &bull; 250 Mintage</span>
        <p class="edition-desc">
          Double-thick 24K electroplated bullion finish with satin micro-ridges and mirror polished rim. SOLD OUT.
        </p>
        <div class="edition-meta">
          <span>Denomination</span>
          <span class="edition-price">10,000 TOKENS</span>
        </div>
        <button class="buy" disabled>SOLD OUT</button>
      </div>

      <!-- 4. Black (obsidian) (coming soon) -->
      <div class="edition" data-edition="black" data-state="coming-soon">
        <span class="edition-badge">MINTING WINTER 2025</span>
        <div class="edition-canvas-wrapper">
          <canvas class="edition-canvas" width="280" height="280"></canvas>
        </div>
        <h3 class="edition-name">Obsidian Void</h3>
        <span class="edition-sub">Edition IV &bull; Classified Mintage</span>
        <p class="edition-desc">
          Diamond-like carbon (DLC) matte obsidian armor coating over tungsten carbide core. Minting in winter.
        </p>
        <div class="edition-meta">
          <span>Status</span>
          <span class="edition-price">WINTER 2025</span>
        </div>
        <button class="buy" disabled>MINTING WINTER 2025</button>
      </div>
    </div>
